import { defineTheme } from "@astryxdesign/core";
import { neutralTheme } from "@astryxdesign/theme-neutral";

/**
 * Cedar Example 커스텀 테마
 * 
 * Astryx Design System을 기반으로 Cedar Example 프로젝트에 맞는
 * 커스텀 테마를 정의합니다.
 */
const cedarTheme = defineTheme(neutralTheme, {
  color: {
    accent: "#6366f1",
    neutralStyle: "cool",
    contrast: "standard",
  },
  typography: {
    scale: {
      base: 16,
      ratio: 1.25,
    },
    body: {
      family: "Inter",
      fallbacks: ["system-ui", "sans-serif"],
    },
    heading: {
      family: "Inter",
      weight: 600,
    },
    code: {
      family: "JetBrains Mono",
    },
  },
  radius: {
    base: 4,
    multiplier: 1,
  },
  motion: {
    fast: 150,
    medium: 300,
    ratio: 1.5,
    easing: "cubic-bezier(0.4, 0, 0.2, 1)",
  },
  components: {
    Button: {
      variants: {
        primary: {
          backgroundColor: "var(--color-accent)",
          color: "white",
        },
        ghost: {
          backgroundColor: "transparent",
          border: "1px solid var(--color-border-default)",
        },
        danger: {
          backgroundColor: "#ef4444",
          color: "white",
        },
      },
    },
    Card: {
      variants: {
        elevated: {
          boxShadow: "0 4px 6px -1px rgb(0 0 0 / 0.1)",
        },
        outlined: {
          border: "1px solid var(--color-border-default)",
        },
      },
    },
  },
});

export default cedarTheme;

import "@astryxdesign/core";

/**
 * Cedar Example 커스텀 배리언트 타입 선언
 */

declare module "@astryxdesign/core" {
  export interface ButtonProps {
    variant?: "primary" | "ghost" | "danger" | "default";
  }

  export interface CardProps {
    variant?: "elevated" | "outlined" | "default";
  }
}

import { Theme } from "@astryxdesign/core";
import { useTheme } from "@astryxdesign/core";
import cedarTheme from "./theme";

/**
 * Playground 페이지 컴포넌트
 * useTheme hook 사용 예시
 */
function PlaygroundPage() {
  const theme = useTheme();

  const containerStyle: React.CSSProperties = {
    padding: "2rem",
    maxWidth: "1200px",
    margin: "0 auto",
  };

  const headerStyle: React.CSSProperties = {
    marginBottom: "2rem",
  };

  const titleStyle: React.CSSProperties = {
    fontSize: "var(--text-heading-1-size)",
    fontWeight: "var(--text-heading-1-weight)",
    color: theme.tokens.color.textPrimary,
    marginBottom: "0.5rem",
  };

  const subtitleStyle: React.CSSProperties = {
    fontSize: "var(--text-body-size)",
    color: theme.tokens.color.textSecondary,
  };

  const cardStyle: React.CSSProperties = {
    padding: "1.5rem",
    borderRadius: "var(--radius-element)",
    backgroundColor: theme.tokens.color.backgroundPrimary,
    border: "1px solid var(--color-border-default)",
    marginBottom: "1rem",
  };

  const gridStyle: React.CSSProperties = {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "1rem",
    marginTop: "1.5rem",
  };

  const badgeStyle: React.CSSProperties = {
    display: "inline-block",
    padding: "0.25rem 0.75rem",
    borderRadius: "9999px",
    fontSize: "0.875rem",
    fontWeight: 500,
    backgroundColor: theme.tokens.color.accent,
    color: "white",
  };

  return (
    <div style={containerStyle}>
      <header style={headerStyle}>
        <h1 style={titleStyle}>Cedar Example Playground</h1>
        <p style={subtitleStyle}>
          Current theme mode: {theme.mode} (resolved: {theme.resolvedMode})
        </p>
      </header>

      <div style={gridStyle}>
        <div style={cardStyle}>
          <span style={badgeStyle}>Theme Active</span>
          <h2 style={{ marginTop: "1rem", marginBottom: "0.5rem" }}>Custom Theme</h2>
          <p style={{ color: theme.tokens.color.textSecondary }}>
            이 페이지는 Astryx Design System의 커스텀 테마를 사용하여 스타일링되었습니다.
          </p>
        </div>

        <div style={cardStyle}>
          <h2 style={{ marginBottom: "0.5rem" }}>Design Tokens</h2>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
            <div>
              <strong>Accent:</strong>{" "}
              <span style={{ color: theme.tokens.color.accent }}>
                {theme.tokens.color.accent}
              </span>
            </div>
            <div>
              <strong>Background:</strong>{" "}
              <span style={{ color: theme.tokens.color.backgroundPrimary }}>
                {theme.tokens.color.backgroundPrimary}
              </span>
            </div>
          </div>
        </div>

        <div style={cardStyle}>
          <h2 style={{ marginBottom: "0.5rem" }}>Motion</h2>
          <p style={{ color: theme.tokens.color.textSecondary }}>
            애니메이션 지속 시간:
            <br />
            Fast: {theme.tokens.duration.fast}ms
            <br />
            Medium: {theme.tokens.duration.medium}ms
          </p>
        </div>
      </div>

      <div style={{ marginTop: "2rem", display: "flex", gap: "1rem" }}>
        <button
          onClick={() => theme.setMode("light")}
          style={{
            padding: "0.5rem 1rem",
            borderRadius: "var(--radius-element)",
            border: "1px solid var(--color-border-default)",
            backgroundColor: "transparent",
            cursor: "pointer",
          }}
        >
          Light Mode
        </button>
        <button
          onClick={() => theme.setMode("dark")}
          style={{
            padding: "0.5rem 1rem",
            borderRadius: "var(--radius-element)",
            border: "1px solid var(--color-border-default)",
            backgroundColor: "transparent",
            cursor: "pointer",
          }}
        >
          Dark Mode
        </button>
        <button
          onClick={() => theme.setMode("system")}
          style={{
            padding: "0.5rem 1rem",
            borderRadius: "var(--radius-element)",
            border: "1px solid var(--color-border-default)",
            backgroundColor: "transparent",
            cursor: "pointer",
          }}
        >
          System Mode
        </button>
      </div>
    </div>
  );
}

/**
 * App 컴포넌트
 * Theme Provider로 전체 앱을 감싸서 커스텀 테마를 적용합니다.
 */
function App() {
  return (
    <Theme theme={cedarTheme} mode="system">
      <PlaygroundPage />
    </Theme>
  );
}

export default App;

